CREATE OR REPLACE FUNCTION public.create_ticket_order_reserved(p_user uuid, p_event uuid, p_email text, p_items jsonb, p_promo_code text DEFAULT NULL::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ declare ev public.events%rowtype; oid uuid; cur text:='EUR'; sub integer:=0; disc integer:=0; it jsonb; pr public.ticket_products%rowtype; qty integer; promo public.ticket_promotions%rowtype; promo_ok boolean:=false; line_disc integer; override_disc integer; d date; cap integer; used integer; units integer; begin select * into ev from public.events where id=p_event for update; if not found then return json_build_object('ok',false,'error','event_not_found'); end if; if not ev.tickets_open then return json_build_object('ok',false,'error','ticket_sales_closed'); end if; if p_items is null or jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items)=0 then return json_build_object('ok',false,'error','invalid_cart'); end if; perform 1 from public.event_daily_capacity where event_id=p_event order by access_date for update; if p_promo_code is not null and btrim(p_promo_code)<>'' then select * into promo from public.ticket_promotions where upper(code)=upper(btrim(p_promo_code)) and active=true and starts_at<=now() and ends_at>=now() limit 1; if not found then return json_build_object('ok',false,'error','invalid_or_expired_promo'); end if; promo_ok:=true; end if; insert into public.ticket_orders(user_id,event_id,status,currency,subtotal_cents,total_cents,customer_email,promotion_id,promo_code,discount_cents) values(p_user,p_event,'pending','EUR',0,0,p_email,case when promo_ok then promo.id end,case when promo_ok then promo.code end,0) returning id into oid; for it in select * from jsonb_array_elements(p_items) loop qty:=greatest(0,floor(coalesce((it->>'quantity')::numeric,0)))::int; if qty<1 then raise exception 'invalid_quantity'; end if; select * into pr from public.ticket_products where id=(it->>'productId')::uuid for update; if not found or pr.event_id<>p_event or not pr.active then raise exception 'invalid_product'; end if; if pr.sales_start is not null and pr.sales_start>now() then raise exception 'sales_not_started'; end if; if pr.sales_end is not null and pr.sales_end<now() then raise exception 'sales_ended'; end if; if qty<pr.min_per_order then raise exception 'minimum_quantity_not_met'; end if; if qty>pr.max_per_order then raise exception 'quantity_too_high'; end if; units:=qty*greatest(pr.group_size,1); if pr.stock_total is not null and pr.sold_count+pr.reserved_count+units>pr.stock_total then raise exception 'sold_out'; end if; for d in select access_date from public.event_daily_capacity where event_id=p_event and public.ticket_product_covers_day(pr.access_date,pr.access_start_date,pr.access_days,ev.starts_on,access_date) order by access_date loop select capacity into cap from public.event_daily_capacity where event_id=p_event and access_date=d; select coalesce(sum(oi.quantity*oi.group_size),0) into used from public.ticket_order_items oi join public.ticket_orders o on o.id=oi.order_id join public.ticket_products tp on tp.id=oi.product_id where o.event_id=p_event and o.status in ('pending','paid') and public.ticket_product_covers_day(tp.access_date,tp.access_start_date,tp.access_days,ev.starts_on,d); if used+units>cap then delete from public.ticket_orders where id=oid; return json_build_object('ok',false,'error','sold_out_for_day','date',d,'remaining',greatest(0,cap-used)); end if; end loop; line_disc:=0; if promo_ok and pr.promo_eligible then select x.discount_value into override_disc from public.ticket_promotion_products x where x.promotion_id=promo.id and x.product_id=pr.id; if found and promo.discount_type='fixed_per_unit' then line_disc:=least(pr.price_cents,coalesce(override_disc,promo.discount_value))*qty; end if; end if; insert into public.ticket_order_items(order_id,product_id,product_code,product_name,unit_price_cents,quantity,group_size,access_days,access_date) values(oid,pr.id,pr.code,pr.name,pr.price_cents,qty,pr.group_size,pr.access_days,pr.access_date); update public.ticket_products set reserved_count=reserved_count+units,updated_at=now() where id=pr.id; sub:=sub+pr.price_cents*qty; disc:=disc+line_disc; end loop; update public.ticket_orders set subtotal_cents=sub,discount_cents=disc,total_cents=greatest(0,sub-disc),updated_at=now() where id=oid; return json_build_object('ok',true,'order_id',oid,'currency',cur,'subtotal_cents',sub,'discount_cents',disc,'total_cents',greatest(0,sub-disc)); exception when others then if oid is not null then perform public.release_ticket_order(oid,'cancelled'); end if; return json_build_object('ok',false,'error',sqlerrm); end $function$
